/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg set = 0;
  reg [3:0] set_num = 0;
  wire [3:0] number;
  wire zero;

  TopModule dut(.clk(clk), .rst_n(rst_n), .set(set), .set_num(set_num), .number(number), .zero(zero));

  always #5 clk = ~clk;

  task show;
    "'$display("t=%0t rst_n=%b set=%b set_num=%h number=%h zero=%b", $time, rst_n, set, set_num, number, zero);
  endtask

  initial begin
    show();
    #2; rst_n = 0; show();
    #6; rst_n = 1; show();
    @(posedge clk); #1; show();
    @(posedge clk); #1; show();
    set = 1; set_num = 4'"'hf;
    @(posedge clk); #1; show();
    set = 0;
    @(posedge clk); #1; show();
    set = 1; set_num = 4'h0;
    @(posedge clk); #1; show();
    set = 0;
    @(posedge clk); #1; show();
    "'$finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

